    function handleAllocationHoursDetailOverlay(event) { if (event.target === event.currentTarget) closeAllocationHoursDetail(); }

    function renderSummaryViews() {
      if (window.TipOutScenarioSource && window.TipOutScenarioSource.withReadCache) {
        return window.TipOutScenarioSource.withReadCache(renderSummaryViewsFromFacts);
      }
      return renderSummaryViewsFromFacts();
    }

    function renderSummaryViewsFromFacts() {
      if (window.TipOutScenarioList) window.TipOutScenarioList.mount();
      var dailyRows = activeSummaryView === 'employee' ? buildEmployeeSummaryDailyDataset() : buildDailyDataset(getFilteredEmployees());
      var allocatedDates = getAllocatedDates();
      if (activeSummaryView === 'employee') {
        document.getElementById('dailySummaryList').innerHTML = '';
        var allAggregates = TipOutSummaryUi.aggregateEmployeeDailyDatasets(dailyRows);
        allEmployeeSummaryAggregates = allAggregates;
        populateEmployeeSummaryRoleFilter(allAggregates);
        renderEmployeeSummaryEmployeeOptions(allAggregates);
        var employeeFilters = {
          roles: employeeSummaryFilters.role ? [employeeSummaryFilters.role] : [],
          employeeScope: employeeSummaryFilters.employeeScope,
          statuses: employeeSummaryFilters.statuses
        };
        visibleEmployeeSummaryAggregates = TipOutSummaryUi.filterAndSortEmployeeAggregates(allAggregates, employeeFilters, employeeSummarySort);
        var eligibleIds = visibleEmployeeSummaryAggregates.map(function(item) { return item.employeeId; });
        var roleAggregateOptions = { role: employeeSummaryFilters.role };
        if (employeeSummaryFilters.employeeScope.mode === 'subset' || employeeSummaryFilters.statuses.length) {
          roleAggregateOptions.employeeIds = eligibleIds;
        }
        var roleAggregates = TipOutSummaryUi.aggregateRoleDailyDatasets(dailyRows, roleAggregateOptions);
        renderEmployeeRoleSummaryCards(roleAggregates);
        updateEmployeeSummarySortHeaders();
        renderEmployeeReconciliationList(visibleEmployeeSummaryAggregates);
      } else {
        visibleDailySummaryRows = TipOutSummaryUi.filterDailyRowsByAllocationStatus(dailyRows, dateSummaryFilters.allocationStatus);
        visibleDailySummaryRows = TipOutSummaryUi.filterDailyRowsByBusinessStatus(visibleDailySummaryRows, dateSummaryFilters.businessStatus);
        if (dateSummaryFilters.payoutStatus) visibleDailySummaryRows = visibleDailySummaryRows.filter(function(row) {
          return payoutViewForRow(row).key === dateSummaryFilters.payoutStatus;
        });
        renderSummaryOverview(visibleDailySummaryRows, allocatedDates);
        visibleEmployeeSummaryAggregates = [];
        renderEmployeeRoleSummaryCards([]);
        document.getElementById('employeeReconciliationList').innerHTML = '';
        document.getElementById('employeeReconciliationEmpty').hidden = true;
        renderDateTaskList(visibleDailySummaryRows);
      }
      updateAllocateButton();
    }

    function renderDailySummaryList() { renderSummaryViews(); }

    function getVisibleEmployeeSummaryAggregates() {
      return visibleEmployeeSummaryAggregates.slice();
    }

    function getVisibleDailySummaryRows() {
      return TipOutSummaryDateSort.sortRows(visibleDailySummaryRows, summaryDateSort);
    }

    function updateAllocateButton() {
      var dates = getDateRange();
      var allocatedDates = getAllocatedDates();
      var hasAllocated = dates.some(function(k) { return allocatedDates.has(k); });
      var btn = document.getElementById('allocateBtn');
      if (btn) btn.textContent = hasAllocated ? '重新分配小费' : '批量分配小费';
    }

    function hasTipRules() {
      return window.ruleData && ruleData.getRules && ruleData.getRules().length > 0;
    }

    function redirectToTipRulesWhenMissing() {
      if (!hasTipRules()) {
        showNotification('请先创建小费分配规则', 'error');
        setTimeout(function() { window.location.href = 'rules.html'; }, 1500);
        return true;
      }
      return false;
    }

    function validateAllocationScope(scope) {
      if (!scope.store) return { field: 'store', message: '请选择门店' };
      if (!scope.startDate) return { field: 'dateStart', message: '请选择起始日期' };
      if (!scope.endDate) return { field: 'dateEnd', message: '请选择终止日期' };
      if (scope.startDate > scope.endDate) return { field: 'dateStart', message: '开始日期不能晚于结束日期' };
      return null;
    }

    function allocationFieldElement(field) {
      var ids = { store: 'allocationStore', dateStart: 'allocationDateStart', dateEnd: 'allocationDateEnd' };
      return document.getElementById(ids[field]);
    }

    function showAllocationScopeError(error) {
      ['allocationStore', 'allocationDateStart', 'allocationDateEnd'].forEach(function(id) {
        var field = document.getElementById(id);
        if (field) field.removeAttribute('aria-invalid');
      });
      var message = document.getElementById('allocationScopeError');
      message.hidden = !error;
      message.textContent = error ? error.message : '';
      if (error) {
        var field = allocationFieldElement(error.field);
        if (field) { field.setAttribute('aria-invalid', 'true'); field.focus(); }
      }
    }

    function setAllocationSubmitting(submitting) {
      allocationSubmitting = submitting;
      ['confirmAllocateBtn', 'cancelTipAllocationBtn', 'closeTipAllocationModalBtn', 'allocateBtn'].forEach(function(id) {
        var button = document.getElementById(id);
        if (button) button.disabled = submitting;
      });
      var confirmButton = document.getElementById('confirmAllocateBtn');
      if (confirmButton) confirmButton.textContent = submitting ? '分配中…' : '分配小费';
    }

    function openTipAllocationModal() {
      if (redirectToTipRulesWhenMissing()) return;
      var pageStore = document.getElementById('storeSelect');
      var selectedStore = pageStore ? pageStore.value : '';
      if (window.TipOutRosterDirectory && TipOutRosterDirectory.validateRuleReferences && window.ruleData) {
        var invalidRule = ruleData.getRulesForStore(selectedStore).find(function(rule) {
          return TipOutRosterDirectory.validateRuleReferences(rule, selectedStore).length > 0;
        });
        if (invalidRule) {
          showNotification('规则「' + (invalidRule.ruleName || '未命名规则') + '」引用的角色或员工已失效，请先修正规则', 'error');
          return;
        }
      }
      var modalStore = document.getElementById('allocationStore');
      modalStore.innerHTML = pageStore.innerHTML;
      modalStore.value = pageStore.value;
      document.getElementById('allocationDateStart').value = document.getElementById('dateStart').value;
      document.getElementById('allocationDateEnd').value = document.getElementById('dateEnd').value;
      showAllocationScopeError(null);
      var modal = document.getElementById('tipAllocationModal');
      modal.classList.add('show');
      modal.setAttribute('aria-hidden', 'false');
      var content = document.querySelector('.team-tips-page .content-area');
      if (content) content.setAttribute('inert', '');
      modalStore.focus();
    }

    function closeTipAllocationModal(force) {
      if (allocationSubmitting && !force) return;
      var modal = document.getElementById('tipAllocationModal');
      modal.classList.remove('show');
      modal.setAttribute('aria-hidden', 'true');
      var content = document.querySelector('.team-tips-page .content-area');
      if (content) content.removeAttribute('inert');
      var trigger = document.getElementById('allocateBtn');
      if (trigger) trigger.focus();
    }

    function handleTipAllocationOverlayClick(event) {
      if (event.target === event.currentTarget) closeTipAllocationModal();
    }

    function syncPageFiltersToAllocationScope(scope) {
      document.getElementById('storeSelect').value = scope.store;
      document.getElementById('dateStart').value = scope.startDate;
      document.getElementById('dateEnd').value = scope.endDate;
      updateEmployeeFilter(true);
    }

    function executeTipAllocationScope(scope) {
      invalidateDayPipelineCache();
      var dates = buildDateRange(scope.startDate, scope.endDate);
      var statusByDate = Object.create(null);
      buildDailyDataset(getStoreEmployees()).forEach(function(row) { statusByDate[row.dateKey] = row.businessStatusResult; });
      var skippedClosedCount = 0;
      var skippedPaidCount = 0;
      dates = dates.filter(function(dateKey) {
        var result = statusByDate[dateKey];
        var allowed = result && result.allocatable;
        if (!allowed) skippedClosedCount += 1;
        if (allowed && window.TipOutDateState && TipOutDateState.inspect(scope.store, dateKey).locked) {
          skippedPaidCount += 1;
          allowed = false;
        }
        return allowed;
      });
      if (!dates.length) {
        var closedError = new Error(skippedPaidCount ? '所选日期均已发放或不可修改，未执行分配' : '所选日期均未营业，无法进行小费分配');
        closedError.allocationStage = 'eligibility';
        throw closedError;
      }
      var allocatedDates = getAllocatedDatesForStore(scope.store);
      dates.forEach(function(k) { allocatedDates.add(k); });
      try {
        saveAllocatedDatesForStore(scope.store, allocatedDates);
      } catch (error) {
        error.allocationStage = 'write';
        throw error;
      }
      try {
        if (window.TipOutPayrollBridge && TipOutPayrollBridge.syncAfterAllocation) {
        TipOutPayrollBridge.syncAfterAllocation(
            scope.store,
            scope.startDate,
            scope.endDate
        );
        }
      } catch (error) {
        error.allocationStage = 'payroll';
        throw error;
      }
      return { successCount: dates.length, paidSkippedCount: skippedPaidCount, closedSkippedCount: skippedClosedCount };
    }

    function submitTipAllocationScope() {
      if (allocationSubmitting) return;
      var scope = Object.freeze({
        store: (document.getElementById('allocationStore').value || '').trim(),
        startDate: document.getElementById('allocationDateStart').value,
        endDate: document.getElementById('allocationDateEnd').value
      });
      var validationError = validateAllocationScope(scope);
      if (validationError) { showAllocationScopeError(validationError); return; }
      showAllocationScopeError(null);
      setAllocationSubmitting(true);
      try {
        var allocationResult = executeTipAllocationScope(scope);
        syncPageFiltersToAllocationScope(scope);
        renderDailySummaryList();
        setAllocationSubmitting(false);
        closeTipAllocationModal(true);
        showNotification('小费分配完成' + (allocationResult.paidSkippedCount ? '，已发放日期跳过 ' + allocationResult.paidSkippedCount + ' 天' : '') + (allocationResult.closedSkippedCount ? '，未营业日期跳过 ' + allocationResult.closedSkippedCount + ' 天' : ''), 'success');
      } catch (error) {
        setAllocationSubmitting(false);
        if (error && (error.allocationStage === 'write' || error.allocationStage === 'payroll')) {
          syncPageFiltersToAllocationScope(scope);
          renderDailySummaryList();
          closeTipAllocationModal(true);
          showNotification(
            error.allocationStage === 'payroll'
              ? '分配结果已保存，但薪资同步失败，请重试同步'
              : '分配未完整完成，请检查结果后重试',
            'error'
          );
          return;
        }
        showNotification(error && error.message ? error.message : '小费分配失败，请重试', 'error');
      }
    }

    function doAllocateTips() {
      openTipAllocationModal();
    }

    async function doCancelAllocate() {
      invalidateDayPipelineCache();
      var dates = getDateRange();
      var storeSel = document.getElementById('storeSelect');
      var storeVal = storeSel ? (storeSel.value || '').trim() : '';
      var paidSkipped = 0;
      var canceledCount = 0;
      for (var i = 0; i < dates.length; i += 1) {
        if (!TipOutAllocationResults.isAllocated(storeVal, dates[i])) continue;
        try { await TipOutAllocationResults.cancel(storeVal, dates[i]); canceledCount += 1; }
        catch (error) { if (/已发放|锁定/.test(error.message || '')) paidSkipped += 1; else throw error; }
      }
      renderDailySummaryList();
      if (canceledCount > 0 && window.TipOutPayrollBridge && TipOutPayrollBridge.syncAfterAllocation) {
        var ds = document.getElementById('dateStart');
        var de = document.getElementById('dateEnd');
        TipOutPayrollBridge.syncAfterAllocation(
          storeVal,
          ds ? ds.value : '',
          de ? de.value : ''
        );
      }
      showNotification(paidSkipped ? (canceledCount ? '已取消 ' + canceledCount + ' 天；已发放日期跳过 ' + paidSkipped + ' 天' : '所选范围均已发放，未执行任何变更') : '已取消分配，状态已恢复为待分配', 'info');
    }

    function getFilteredEmployees() {
      var roles = getSelectedRoles();
      var empNames = getSelectedEmployees();
      var list = employees;
      var storeSelect = document.getElementById('storeSelect');
      var selectedStore = canonicalEmployeeStore(storeSelect ? storeSelect.value : '');
      if (selectedStore) list = list.filter(function(e) { return !e.store || canonicalEmployeeStore(e.store) === selectedStore; });
      if (roles.length > 0) list = list.filter(function(e) { return roles.indexOf(e.role) >= 0; });
      if (empNames.length > 0) list = list.filter(function(e) { return empNames.indexOf(e.name) >= 0; });
      return list;
    }

    function getStoreEmployees() {
      var storeSelect = document.getElementById('storeSelect');
      var selectedStore = canonicalEmployeeStore(storeSelect ? storeSelect.value : '');
      if (!selectedStore) return employees.slice();
      var storeEmployees = employees.filter(function(employee) {
        return !employee.store || canonicalEmployeeStore(employee.store) === selectedStore;
      });
      if (!window.TipOutRosterDirectory || !TipOutRosterDirectory.resolveReceiverEmployees || !window.ruleData) return storeEmployees;
      var rawStore = storeSelect ? storeSelect.value : '';
      var rules = ruleData.getRulesForStore ? ruleData.getRulesForStore(rawStore) : ruleData.getRules().filter(function(rule) {
        return canonicalEmployeeStore(rule.store) === selectedStore;
      });
      var receiverIds = Object.create(null), receiverNames = Object.create(null);
      var contributorIds = Object.create(null), contributorNames = Object.create(null), contributorRoles = Object.create(null);
      var allEmployeesContribute = false;
      rules.forEach(function(rule) {
        var resolution = TipOutRosterDirectory.resolveReceiverEmployees(rule, rawStore);
        if (!resolution.issues.length) resolution.employees.forEach(function(employee) {
          receiverIds[employee.id] = true;
          receiverNames[employee.name] = true;
        });
        var config = rule.deductConfig || {};
        var entries = ['salesPct', 'personalSalesPct', 'tipIncome'].reduce(function(list, key) {
          var value = config[key];
          return value ? list.concat(Array.isArray(value) ? value : [value]) : list;
        }, []);
        if (!entries.length) {
          var legacyEmployees = rule.deductEmployees;
          var names = Array.isArray(legacyEmployees) ? legacyEmployees :
            (legacyEmployees && (legacyEmployees.employee || legacyEmployees.employees)) || [];
          entries = [{ employee: names, roles: rule.deductRoles || [] }];
          if (!names.length && !(rule.deductRoles || []).length) allEmployeesContribute = true;
        }
        entries.forEach(function(entry) {
          (entry.roles || entry.role || []).forEach(function(role) { contributorRoles[String(role)] = true; });
          (entry.employees || entry.employee || []).forEach(function(employee) {
            var ref = String(employee && (employee.employeeId || employee.id || employee.name) || employee);
            contributorIds[ref.replace(/^roster:/, '')] = true;
            contributorNames[ref] = true;
          });
        });
      });
      return storeEmployees.filter(function(employee) {
        var rawId = String(employee.employeeId || '').replace(/^roster:/, '');
        return allEmployeesContribute || !!receiverIds[rawId] || !!receiverNames[employee.name] ||
          !!contributorIds[rawId] || !!contributorNames[employee.name] || !!contributorRoles[employee.role];
      });
    }

    function toggleFold(empId) {
      const section = document.getElementById(empId);
      const detail = section.querySelector('.employee-detail');
      const btn = section.querySelector('.fold-btn span');
      if (detail.style.maxHeight === '0px') { detail.style.maxHeight = '2000px'; btn.textContent = '收起'; }
      else { detail.style.maxHeight = '0px'; btn.textContent = '展开'; }
    }

    function initStoreSelect() {
      var sel = document.getElementById('storeSelect');
      if (!sel) return;
      var rules = window.ruleData && ruleData.getRules ? ruleData.getRules() : [];
      var seen = {};
      var stores = [];
      rules.forEach(function(r) {
        var s = (r.store || '').trim();
        if (s && !seen[s]) { seen[s] = 1; stores.push(s); }
      });
      sel.innerHTML = '<option value="">请选择门店</option>' + stores.map(function(s) {
        return '<option value="' + s + '">' + s + '</option>';
      }).join('');
      if (stores.length > 0 && !sel.value) sel.value = stores[0];
    }

    document.addEventListener('change', function(e) {
      var target = e.target;
      var ms = target && target.closest && target.closest('.filter-bar .multi-select');
      if (!ms) return;
      var id = ms.id;
      if (target.dataset && target.dataset.selectAll !== undefined) {
        toggleSelectAll(id, target.checked);
        return;
      }
      refreshIndexMultiTags(id);
      syncSelectAllState(id);
      if (id === 'roleFilter') updateEmployeeFilter();
      else if (id === 'employeeFilter') renderDailySummaryList();
      else if (id === 'employeeSummaryEmployeeFilter') handleEmployeeSummaryEmployeeChange();
    });
    document.addEventListener('click', function(e) {
      if (!e.target.closest || !e.target.closest('.filter-bar .multi-select')) {
        document.querySelectorAll('.filter-bar .multi-select.open').forEach(function(ms) { ms.classList.remove('open'); });
      }
    });
    document.addEventListener('keydown', function(event) {
      if (event.key === 'Escape' && document.getElementById('allocationHoursDetailModal') && document.getElementById('allocationHoursDetailModal').classList.contains('show')) closeAllocationHoursDetail();
      var payoutModal = document.getElementById('confirmPayoutModal');
      if (payoutModal && payoutModal.classList.contains('show') && event.key === 'Escape') {
        event.preventDefault(); closeConfirmPayoutModal(); return;
      }
      var modal = document.getElementById('tipAllocationModal');
      if (!modal || !modal.classList.contains('show')) return;
      if (event.key === 'Escape') {
        event.preventDefault();
        closeTipAllocationModal();
        return;
      }
      if (event.key !== 'Tab') return;
      var focusable = Array.from(modal.querySelectorAll('button:not([disabled]), select:not([disabled]), input:not([disabled])'));
      if (!focusable.length) return;
      var first = focusable[0];
      var last = focusable[focusable.length - 1];
      if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last.focus(); }
      else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first.focus(); }
    });

    function initializeSummaryPage() {
      if (window.TipOutDemoRules) {
        try { window.TipOutDemoRules.ensure(); } catch (_) {}
      }
      initStoreSelect();
      applyDefaultSummaryDateRange();
      syncSummaryDateSortUi();
      var queryView = new URLSearchParams(window.location.search).get('view');
      activeSummaryView = TipOutSummaryUi.resolveSummaryView(
        history.state,
        queryView
      );
      if (queryView && queryView !== 'employee') {
        setSummaryView('date', { historyMode: 'replace' });
        return;
      }
      syncSummaryViewUi();
      if (!restoreSummaryUiState()) {
        updateEmployeeFilter(true);
        renderDailySummaryList();
      }
    }

    document.addEventListener('DOMContentLoaded', initializeSummaryPage);
    window.addEventListener('resize', syncSummaryActionBarBounds);
    window.addEventListener('pageshow', function() {
      restoreSummaryUiState();
      syncSummaryViewUi();
    });
    window.addEventListener('tipout-date-state-changed', function() { renderDailySummaryList(); });
    if (window.BroadcastChannel) {
      var tipoutDateStateChannel = new window.BroadcastChannel('tipout-date-state-changed');
      tipoutDateStateChannel.addEventListener('message', function() { renderDailySummaryList(); });
    }
